/**
 * EIP-712 domain name for Circle Gateway batched payments.
 * Used in the `extra.name` field of PaymentRequirements to identify Circle batching options.
 */
export const CIRCLE_BATCHING_NAME = 'GatewayWalletBatched';

/**
 * Version 1 EIP-712 domain version for Circle Gateway batched payments.
 * Used in the `extra.version` field of PaymentRequirements. Its four-field
 * domain carries no asset.
 */
export const CIRCLE_BATCHING_VERSION = '1';

/**
 * Version 2 EIP-712 domain version for Circle Gateway batched payments. Its
 * domain adds `salt`, set to the asset address left-padded to 32 bytes, so the
 * signature binds the asset.
 */
export const CIRCLE_BATCHING_VERSION_V2 = '2';

/**
 * Every `extra.version` the buyer can sign.
 */
export const CIRCLE_BATCHING_VERSIONS = [
  CIRCLE_BATCHING_VERSION,
  CIRCLE_BATCHING_VERSION_V2,
] as const;

/**
 * The payment scheme used for Circle batching (same as standard x402 exact scheme).
 */
export const CIRCLE_BATCHING_SCHEME = 'exact';

/**
 * Minimum authorization validity window required by Gateway batching.
 */
export const GATEWAY_MIN_AUTH_VALIDITY_SECONDS = 7 * 24 * 60 * 60;

/**
 * Extra validity window so authorizations still satisfy Gateway's minimum
 * after client/server clock differences and request latency.
 */
export const GATEWAY_AUTH_VALIDITY_BUFFER_SECONDS = 100;

/**
 * Authorization validity window the SDK should publish and sign with.
 */
export const GATEWAY_AUTH_VALIDITY_WINDOW_SECONDS =
  GATEWAY_MIN_AUTH_VALIDITY_SECONDS + GATEWAY_AUTH_VALIDITY_BUFFER_SECONDS;

/**
 * Public base URL of the Circle Facilitator x402 API (verify, settle, supported, status).
 */
export const FACILITATOR_URL = 'https://api.circle.com/v1/facilitator/x402';

/**
 * Header carrying the seller proof on keyless Circle Facilitator requests.
 */
export const FACILITATOR_SELLER_PROOF_HEADER = 'Facilitator-Seller-Proof';

/**
 * EIP-712 domain name for Circle Facilitator seller proofs. The domain has no
 * verifyingContract: the verifier is a service, not a contract.
 */
export const FACILITATOR_SELLER_PROOF_DOMAIN_NAME = 'Circle Facilitator Seller Request';

/**
 * EIP-712 domain version for Circle Facilitator seller proofs.
 */
export const FACILITATOR_SELLER_PROOF_DOMAIN_VERSION = '1';

/**
 * Seller proof header layout version understood by the Circle Facilitator.
 */
export const FACILITATOR_SELLER_PROOF_VERSION = 1;

/**
 * Longest issuedAt-to-expiresAt window the Circle Facilitator accepts on a
 * seller proof.
 */
export const FACILITATOR_SELLER_PROOF_MAX_TTL_SECONDS = 5 * 60;

/**
 * How far in the future the Circle Facilitator tolerates a proof's `issuedAt`.
 */
export const FACILITATOR_SELLER_PROOF_MAX_CLOCK_SKEW_SECONDS = 30;

/**
 * Default seller proof lifetime. Short enough to limit replay exposure, long
 * enough to absorb request latency and modest clock skew.
 */
export const FACILITATOR_SELLER_PROOF_TTL_SECONDS = 120;

/**
 * `errorReason` the Circle Facilitator returns from `/settle` when the payment
 * was submitted but its on-chain outcome was not observed within the wait.
 * The seller must not deliver; reconcile via `/status` using the returned
 * `paymentId`.
 */
export const FACILITATOR_SETTLEMENT_PENDING = 'settlement_pending';

/**
 * Default `maxTimeoutSeconds` published for Circle Facilitator payment
 * requirements. Buyers sign `validBefore = now + maxTimeoutSeconds`, so it
 * must comfortably cover the Facilitator's synchronous settlement wait.
 */
export const FACILITATOR_MAX_TIMEOUT_SECONDS = 300;
